/* Northwind design system. @generated by auto-design 0.1.0 from design.config.ts.
   Do not edit by hand: change design.config.ts and run `npx auto-design build`. */

@custom-variant dark (&:where(.dark, .dark *));

@theme {
  /* Locked: Tailwind's defaults for these namespaces are removed. */
  --color-*: initial;
  --font-*: initial;
  --text-*: initial;
  --font-weight-*: initial;
  --tracking-*: initial;
  --leading-*: initial;
  --radius-*: initial;
  --shadow-*: initial;
  --inset-shadow-*: initial;
  --drop-shadow-*: initial;
  --text-shadow-*: initial;
  --blur-*: initial;
  --ease-*: initial;
  --animate-*: initial;

  --font-sans: "Instrument Sans Variable", "Instrument Sans", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "JetBrains Mono Variable", "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  --font-display: "Instrument Serif", "Instrument Serif", ui-serif, Georgia, serif;
  --text-xs: 0.75rem;
  --text-xs--line-height: 1.5;
  --text-xs--letter-spacing: 0.01em;
  --text-sm: 0.8125rem;
  --text-sm--line-height: 1.45;
  --text-sm--letter-spacing: 0em;
  --text-base: 1rem;
  --text-base--line-height: 1.5;
  --text-base--letter-spacing: 0em;
  --text-lg: 1.25rem;
  --text-lg--line-height: 1.45;
  --text-lg--letter-spacing: -0.005em;
  --text-xl: 1.625rem;
  --text-xl--line-height: 1.35;
  --text-xl--letter-spacing: -0.01em;
  --text-2xl: 2rem;
  --text-2xl--line-height: 1.25;
  --text-2xl--letter-spacing: -0.015em;
  --text-3xl: 2.5rem;
  --text-3xl--line-height: 1.2;
  --text-3xl--letter-spacing: -0.02em;
  --text-4xl: 3rem;
  --text-4xl--line-height: 1.1;
  --text-4xl--letter-spacing: -0.025em;
  --text-5xl: 3.875rem;
  --text-5xl--line-height: 1.05;
  --text-5xl--letter-spacing: -0.03em;
  --text-6xl: 4.75rem;
  --text-6xl--line-height: 1;
  --text-6xl--letter-spacing: -0.03em;
  --font-weight-normal: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --tracking-tight: -0.02em;
  --tracking-normal: 0em;
  --tracking-wide: 0.04em;
  --leading-none: 1;
  --leading-tight: 1.25;
  --leading-snug: 1.4;
  --leading-normal: 1.5;
  --leading-relaxed: 1.65;
  --radius-sm: max(0px, calc(var(--radius) - 4px));
  --radius-md: max(0px, calc(var(--radius) - 2px));
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
  --shadow-xs: 0 0 #0000;
  --shadow-sm: 0 0 #0000;
  --shadow-md: 0 0 #0000;
  --shadow-lg: 0px 12px 32px -8px oklch(0 0 0 / 0.32);
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.87, 0, 0.13, 1);
  --animate-enter: ad-enter var(--duration-base) var(--ease-out) both;
  --animate-exit: ad-exit var(--duration-fast) var(--ease-in-out) both;
  --animate-fade-in: ad-fade-in var(--duration-base) var(--ease-out) both;
  --animate-fade-out: ad-fade-out var(--duration-fast) var(--ease-in-out) both;
  --animate-pulse: ad-pulse 2s var(--ease-in-out) infinite;
  --animate-spin: ad-spin 1s linear infinite;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-success: var(--success);
  --color-success-foreground: var(--success-foreground);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-overlay: var(--overlay);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
  --color-transparent: transparent;
  --color-current: currentColor;
}

:root:root {
  --radius: 0.5rem;
  --duration-fast: 150ms;
  --duration-base: 220ms;
  --duration-slow: 320ms;
  --enter-scale: 0.95;
  --enter-distance: 8px;
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0.006 70);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0.006 70);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0.006 70);
  --primary: oklch(0.4 0.068 63.2);
  --primary-foreground: oklch(0.985 0.003 70);
  --secondary: oklch(0.967 0.004 70);
  --secondary-foreground: oklch(0.205 0.007 70);
  --muted: oklch(0.967 0.004 70);
  --muted-foreground: oklch(0.541 0.01 70);
  --accent: oklch(0.967 0.004 70);
  --accent-foreground: oklch(0.205 0.007 70);
  --destructive: oklch(0.555 0.22 27);
  --destructive-foreground: oklch(0.985 0.003 70);
  --success: oklch(0.54 0.142 152);
  --success-foreground: oklch(0.985 0.003 70);
  --warning: oklch(0.72 0.152 75);
  --warning-foreground: oklch(0.145 0.006 70);
  --border: oklch(0.87 0.008 70);
  --input: oklch(0.87 0.008 70);
  --ring: oklch(0.4 0.068 63.2);
  --overlay: oklch(0 0 0 / 40%);
  --chart-1: oklch(0.4 0.068 63.2);
  --chart-2: oklch(0.72 0.12 103.2);
  --chart-3: oklch(0.6 0.11 223.2);
  --chart-4: oklch(0.78 0.1 3.2);
  --chart-5: oklch(0.708 0.01 70);
  --sidebar: oklch(0.985 0.003 70);
  --sidebar-foreground: oklch(0.145 0.006 70);
  --sidebar-primary: oklch(0.4 0.068 63.2);
  --sidebar-primary-foreground: oklch(0.985 0.003 70);
  --sidebar-accent: oklch(0.967 0.004 70);
  --sidebar-accent-foreground: oklch(0.205 0.007 70);
  --sidebar-border: oklch(0.922 0.006 70);
  --sidebar-ring: oklch(0.4 0.068 63.2);
}

:root.dark {
  --background: oklch(0.145 0.006 70);
  --foreground: oklch(0.985 0.003 70);
  --card: oklch(0.145 0.006 70);
  --card-foreground: oklch(0.985 0.003 70);
  --popover: oklch(0.145 0.006 70);
  --popover-foreground: oklch(0.985 0.003 70);
  --primary: oklch(0.72 0.077 63.2);
  --primary-foreground: oklch(0.145 0.006 70);
  --secondary: oklch(0.269 0.008 70);
  --secondary-foreground: oklch(0.985 0.003 70);
  --muted: oklch(0.269 0.008 70);
  --muted-foreground: oklch(0.708 0.01 70);
  --accent: oklch(0.269 0.008 70);
  --accent-foreground: oklch(0.985 0.003 70);
  --destructive: oklch(0.72 0.174 27);
  --destructive-foreground: oklch(0.145 0.006 70);
  --success: oklch(0.72 0.144 152);
  --success-foreground: oklch(0.145 0.006 70);
  --warning: oklch(0.72 0.152 75);
  --warning-foreground: oklch(0.145 0.006 70);
  --border: oklch(0.269 0.008 70);
  --input: oklch(0.371 0.009 70);
  --ring: oklch(0.72 0.077 63.2);
  --overlay: oklch(0 0 0 / 60%);
  --chart-1: oklch(0.72 0.077 63.2);
  --chart-2: oklch(0.75 0.12 103.2);
  --chart-3: oklch(0.68 0.11 223.2);
  --chart-4: oklch(0.8 0.1 3.2);
  --chart-5: oklch(0.556 0.01 70);
  --sidebar: oklch(0.205 0.007 70);
  --sidebar-foreground: oklch(0.985 0.003 70);
  --sidebar-primary: oklch(0.72 0.077 63.2);
  --sidebar-primary-foreground: oklch(0.145 0.006 70);
  --sidebar-accent: oklch(0.269 0.008 70);
  --sidebar-accent-foreground: oklch(0.985 0.003 70);
  --sidebar-border: oklch(0.269 0.008 70);
  --sidebar-ring: oklch(0.72 0.077 63.2);
}

@keyframes ad-enter {
  from {
    opacity: 0;
    transform: translateY(var(--enter-distance)) scale(var(--enter-scale));
  }
}

@keyframes ad-exit {
  to {
    opacity: 0;
    transform: scale(var(--enter-scale));
  }
}

@keyframes ad-fade-in {
  from {
    opacity: 0;
  }
}

@keyframes ad-fade-out {
  to {
    opacity: 0;
  }
}

@keyframes ad-pulse {
  50% {
    opacity: 0.4;
  }
}

@keyframes ad-spin {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --enter-scale: 1;
    --enter-distance: 0px;
  }
}

@layer base {
  *,
  ::before,
  ::after {
    border-color: var(--color-border);
  }
  html {
    color-scheme: light;
    -webkit-text-size-adjust: 100%;
  }
  html.dark {
    color-scheme: dark;
  }
  body {
    background-color: var(--color-background);
    color: var(--color-foreground);
    font-family: var(--font-sans);
    font-size: var(--text-base);
    line-height: var(--text-base--line-height);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: optimizeLegibility;
  }
  h1, h2, h3, h4 {
    text-wrap: balance;
  }
  p, li, figcaption {
    text-wrap: pretty;
  }
  code, kbd, pre, samp {
    font-family: var(--font-mono);
  }
  :focus-visible {
    outline: 2px solid var(--color-ring);
    outline-offset: 2px;
  }
  ::selection {
    background-color: color-mix(in oklab, var(--color-primary) 22%, transparent);
  }
}

@layer components {
  .shiki,
  .shiki span {
    color: var(--shiki-light);
    font-style: var(--shiki-light-font-style);
  }
  :root.dark .shiki,
  :root.dark .shiki span {
    color: var(--shiki-dark);
    font-style: var(--shiki-dark-font-style);
  }
  .shiki {
    background-color: transparent;
  }
}

/* Inside an MCP Apps host (Claude, ChatGPT). The host owns the canvas, text, borders and
   type; the brand keeps primary actions, focus rings and charts. Set by applyHostContext(). */
:root:root[data-mcp-host] {
  color-scheme: light;
  --background: var(--color-background-primary, oklch(1 0 0));
  --foreground: var(--color-text-primary, oklch(0.145 0.006 70));
  --card: var(--color-background-primary, oklch(1 0 0));
  --card-foreground: var(--color-text-primary, oklch(0.145 0.006 70));
  --popover: var(--color-background-primary, oklch(1 0 0));
  --popover-foreground: var(--color-text-primary, oklch(0.145 0.006 70));
  --secondary: var(--color-background-secondary, oklch(0.967 0.004 70));
  --secondary-foreground: var(--color-text-primary, oklch(0.205 0.007 70));
  --muted: var(--color-background-secondary, oklch(0.967 0.004 70));
  --muted-foreground: var(--color-text-secondary, oklch(0.541 0.01 70));
  --accent: var(--color-background-secondary, oklch(0.967 0.004 70));
  --accent-foreground: var(--color-text-primary, oklch(0.205 0.007 70));
  --destructive: var(--color-text-danger, oklch(0.555 0.22 27));
  --destructive-foreground: var(--color-text-inverse, oklch(0.985 0.003 70));
  --success: var(--color-text-success, oklch(0.54 0.142 152));
  --success-foreground: var(--color-text-inverse, oklch(0.985 0.003 70));
  --warning: var(--color-text-warning, oklch(0.72 0.152 75));
  --warning-foreground: var(--color-text-inverse, oklch(0.145 0.006 70));
  --border: var(--color-border-tertiary, oklch(0.87 0.008 70));
  --input: var(--color-border-primary, oklch(0.87 0.008 70));
  --sidebar: var(--color-background-secondary, oklch(0.985 0.003 70));
  --sidebar-foreground: var(--color-text-primary, oklch(0.145 0.006 70));
  --sidebar-accent: var(--color-background-tertiary, oklch(0.967 0.004 70));
  --sidebar-accent-foreground: var(--color-text-primary, oklch(0.205 0.007 70));
  --sidebar-border: var(--color-border-tertiary, oklch(0.922 0.006 70));
  --radius-sm: var(--border-radius-sm, max(0px, calc(var(--radius) - 4px)));
  --radius-md: var(--border-radius-md, max(0px, calc(var(--radius) - 2px)));
  --radius-lg: var(--border-radius-lg, var(--radius));
  --radius-xl: var(--border-radius-xl, calc(var(--radius) + 4px));
}
:root:root[data-mcp-host].dark, :root:root[data-mcp-host][data-theme="dark"] {
  color-scheme: dark;
  --background: var(--color-background-primary, oklch(0.145 0.006 70));
  --foreground: var(--color-text-primary, oklch(0.985 0.003 70));
  --card: var(--color-background-primary, oklch(0.145 0.006 70));
  --card-foreground: var(--color-text-primary, oklch(0.985 0.003 70));
  --popover: var(--color-background-primary, oklch(0.145 0.006 70));
  --popover-foreground: var(--color-text-primary, oklch(0.985 0.003 70));
  --secondary: var(--color-background-secondary, oklch(0.269 0.008 70));
  --secondary-foreground: var(--color-text-primary, oklch(0.985 0.003 70));
  --muted: var(--color-background-secondary, oklch(0.269 0.008 70));
  --muted-foreground: var(--color-text-secondary, oklch(0.708 0.01 70));
  --accent: var(--color-background-secondary, oklch(0.269 0.008 70));
  --accent-foreground: var(--color-text-primary, oklch(0.985 0.003 70));
  --destructive: var(--color-text-danger, oklch(0.72 0.174 27));
  --destructive-foreground: var(--color-text-inverse, oklch(0.145 0.006 70));
  --success: var(--color-text-success, oklch(0.72 0.144 152));
  --success-foreground: var(--color-text-inverse, oklch(0.145 0.006 70));
  --warning: var(--color-text-warning, oklch(0.72 0.152 75));
  --warning-foreground: var(--color-text-inverse, oklch(0.145 0.006 70));
  --border: var(--color-border-tertiary, oklch(0.269 0.008 70));
  --input: var(--color-border-primary, oklch(0.371 0.009 70));
  --sidebar: var(--color-background-secondary, oklch(0.205 0.007 70));
  --sidebar-foreground: var(--color-text-primary, oklch(0.985 0.003 70));
  --sidebar-accent: var(--color-background-tertiary, oklch(0.269 0.008 70));
  --sidebar-accent-foreground: var(--color-text-primary, oklch(0.985 0.003 70));
  --sidebar-border: var(--color-border-tertiary, oklch(0.269 0.008 70));
}
:root[data-mcp-host],
:root[data-mcp-host] body {
  background: transparent;
}

docs:
Import the fonts once in your root layout: import "@fontsource-variable/instrument-sans"; import "@fontsource-variable/jetbrains-mono"; import "@fontsource/instrument-serif";
Remove any :root/.dark color variables and @theme keys left in your CSS from a template; `npx auto-design check` lists them.
If your Tailwind entry is not app/globals.css, move app/auto-design.css next to it.
